#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
import argparse, base64, hashlib, subprocess, sys

EXPECTED_BRANCH="science/universal-generative-validation-v1"
EXPECTED_HEAD="84e4338ac7b112e9f0fd1844748176a2388ddc8d"
PAYLOAD={'validation/engineered/__init__.py': '', 'validation/engineered/model.py': '', 'validation/engineered/rng.py': '', 'validation/engineered/exact_oracle.py': '', 'validation/engineered/physical.py': '', 'validation/engineered/budget.py': '', 'validation/engineered/compare.py': '', 'validation/engineered/production.py': '', 'validation/engineered/contracts.py': '', 'validation/engineered/metamorphic.py': '', 'validation/engineered/mutants.py': '', 'validation/engineered/mutation_score.py': '', 'validation/engineered/shrink.py': '', 'validation/engineered/ledger.py': '', 'validation/engineered/high_precision.py': '', 'validation/engineered/project_pipeline.py': '', 'validation/engineered/ptmc_oracle.py': '', 'validation/engineered/harness.py': '', 'tests/test_engineered_exact_oracle.py': '', 'tests/test_engineered_degeneracy_boundaries.py': '', 'tests/test_engineered_mutation_score.py': '', 'tests/test_engineered_metamorphic.py': '', 'tests/test_engineered_cofactor_ptmc_rankone.py': '', 'tests/test_engineered_high_precision_conditioning.py': '', 'tests/test_engineered_end_to_end_project.py': '', 'tests/test_engineered_oracle_firewall.py': '', 'tools/run_engineered_falsification_v2.py': '', 'docs/ENGINEERED_FALSIFICATION_V2.md': ''}

FROZEN=(
    'src/cualni_cryst/ct.py',
    'src/cualni_cryst/correspondence.py',
    'src/cualni_cryst/lattice.py',
    'src/cualni_cryst/stretch.py',
    'src/cualni_cryst/ball_james.py',
    'src/cualni_cryst/rank_one.py',
    'src/cualni_cryst/cofactor.py',
    'src/cualni_cryst/ptmc.py',
    'src/cualni_cryst/representation.py',
    'src/cualni_cryst/scientific_contracts.py',
    'src/cualni_cryst/project_io.py',
    'src/cualni_cryst/calculation_service.py',
)

def git(repo,*args,check=True):
    p=subprocess.run(["git","-C",str(repo),*args],text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if check and p.returncode:
        raise RuntimeError("git "+" ".join(args)+"\n"+p.stdout+p.stderr)
    return p

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--repo",required=True)
    args=ap.parse_args()
    repo=Path(args.repo).resolve()

    branch=git(repo,"branch","--show-current").stdout.strip()
    head=git(repo,"rev-parse","HEAD").stdout.strip()
    print("branch:",branch)
    print("HEAD:  ",head)
    if branch!=EXPECTED_BRANCH:
        raise RuntimeError(f"wrong branch: expected {EXPECTED_BRANCH}, got {branch}")
    if head!=EXPECTED_HEAD:
        raise RuntimeError(f"wrong HEAD: expected {EXPECTED_HEAD}, got {head}")

    print("\n=== FROZEN PRODUCTION CORE ===")
    for rel in FROZEN:
        p=repo/rel
        if not p.exists():
            raise RuntimeError("missing frozen production file: "+rel)
        if git(repo,"diff","--quiet","HEAD","--",rel,check=False).returncode:
            raise RuntimeError("production file already modified: "+rel)
        print("clean:",rel,sha(p))

    print("\n=== INSTALL ENGINEERED FALSIFICATION V2 ===")
    for rel,b64 in PAYLOAD.items():
        p=repo/rel
        content=base64.b64decode(b64).decode("utf-8")
        if p.exists() and p.read_text(encoding="utf-8")!=content:
            raise RuntimeError("refusing to overwrite non-identical file: "+rel)
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_text(content,encoding="utf-8")
        print("installed:",rel)

    print("\n=== SYNTAX ===")
    for rel,b64 in PAYLOAD.items():
        if not rel.endswith(".py"):
            continue
        content=base64.b64decode(b64).decode("utf-8")
        compile(content,rel,"exec")
        print("compiled:",rel)

    print("\nproduction code modified: NO")
    print("physical truth generated before crystallographic encoding: YES")
    print("exact rational oracle independent of production: YES")
    print("high-precision differential oracle: YES")
    print("metamorphic representation engine: YES")
    print("condition-aware error budgets: YES")
    print("mutation testing: YES")
    print("counterexample shrinking: YES")
    print("persistent failure ledger: YES")
    print("end-to-end project input path: YES")
    print("\nNEXT:")
    print("python tools/run_engineered_falsification_v2.py --profile quick")
    print("python tools/run_engineered_falsification_v2.py --profile full")
    print("python tools/run_engineered_falsification_v2.py --profile torture")
    return 0

if __name__=="__main__":
    raise SystemExit(main())
